-- TREAN AI core schema
create extension if not exists pgcrypto;
create extension if not exists vector;
create table if not exists public.learning_sources (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, url text not null, title text, source_type text not null default 'youtube', status text not null default 'queued' check(status in ('queued','processing','completed','failed')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,url));
create table if not exists public.processing_jobs (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, source_id uuid not null references public.learning_sources(id) on delete cascade, status text not null default 'queued' check(status in ('queued','processing','completed','failed')), stage text not null default 'queued', attempts int not null default 0, error text, started_at timestamptz, finished_at timestamptz, created_at timestamptz not null default now());
create table if not exists public.transcripts (id uuid primary key default gen_random_uuid(), source_id uuid not null references public.learning_sources(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, language text, content text not null, created_at timestamptz not null default now(), unique(source_id));
create table if not exists public.knowledge_chunks (id uuid primary key default gen_random_uuid(), source_id uuid not null references public.learning_sources(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, chunk_index int not null, content text not null, embedding vector(1536), metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), unique(source_id,chunk_index));
create table if not exists public.summaries (id uuid primary key default gen_random_uuid(), source_id uuid not null references public.learning_sources(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, summary text not null, key_points jsonb not null default '[]'::jsonb, created_at timestamptz not null default now(), unique(source_id));
create table if not exists public.conversations (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, title text not null default 'New chat', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.messages (id uuid primary key default gen_random_uuid(), conversation_id uuid not null references public.conversations(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role text not null check(role in ('user','assistant','system')), content text not null, citations jsonb not null default '[]'::jsonb, created_at timestamptz not null default now());
create index if not exists jobs_status_created_idx on public.processing_jobs(status,created_at);
create index if not exists chunks_user_source_idx on public.knowledge_chunks(user_id,source_id);
create index if not exists messages_conversation_created_idx on public.messages(conversation_id,created_at);
alter table public.learning_sources enable row level security; alter table public.processing_jobs enable row level security; alter table public.transcripts enable row level security; alter table public.knowledge_chunks enable row level security; alter table public.summaries enable row level security; alter table public.conversations enable row level security; alter table public.messages enable row level security;
create policy "Users own learning sources" on public.learning_sources for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy "Users own jobs" on public.processing_jobs for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy "Users own transcripts" on public.transcripts for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy "Users own chunks" on public.knowledge_chunks for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy "Users own summaries" on public.summaries for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy "Users own conversations" on public.conversations for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy "Users own messages" on public.messages for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
grant select,insert,update,delete on public.learning_sources,public.processing_jobs,public.transcripts,public.knowledge_chunks,public.summaries,public.conversations,public.messages to authenticated;
